type Ctx={workspace:string};
async function run(context:Ctx,budgets:CachePartitionBudgetsV1){
 for(const target of declared){
  const partition=budgets[target.partition],base=partition?join(context.workspace,partition.directory,"m",...(target.directory?.split("/")??[])):undefined;
  const present=base!==undefined&&await stat(base).then(row=>row.isDirectory(),()=>false);
  await dedupeTreeV1({base,minimumBytes:1},ports);
 }
}

type Ctx={workspace:string};
async function run(context:Ctx,budgets:CachePartitionBudgetsV1,leaseDirectory:string){
 for(const target of declared){
  const partition=budgets[target.partition],base=partition?join(context.workspace,partition.directory,"m",...(target.directory?.split("/")??[])):undefined;
  const reader=createNativeImageSharedReaderV1({leaseDirectory,imageDirectory:join(context.workspace,partition.directory),signal});
  try{
   const present=base!==undefined&&await reader.run(()=>stat(base).then(row=>row.isDirectory(),()=>false));
   await dedupeTreeV1({base,minimumBytes:1,reader},ports);
  }finally{await reader.close();}
 }
}

